-- Loads HARNESS_WAR_DIAG from one state dump into DuckDB (study/queries_balance.json): replace STATE with the dump path, run with duckdb.connect(<war_gN.duckdb>).execute(<this text>).
create or replace table meta as select humanSeat as human, turn from read_json_auto('STATE', maximum_object_size=1000000000);
create or replace table pl as select unnest(players) p from read_json_auto('STATE', maximum_object_size=1000000000);
create or replace table team as select p.id as player, p.leader as leader, p.war.consider as consider, p.war.plans as plans, p.war.enemyPowerPct as enemy_power_pct, p.war.checks as checks, p.war.declareProb as declare_prob, p.war.ourPower as our_power, p.war.pTotal as p_total, p.war.pLimited as p_limited, p.war.pDogpile as p_dogpile, p.war.nearby as nearby, p.war.distant as distant, p.war.limited as limited, p.war.minAdj as min_adj from pl where p.war is not null;
create or replace table target as select p.id as player, t.team as target, t.att as att, t.noWar as no_war, t.rollTotal as roll_total, t.rollLimited as roll_limited, t.rollDogpile as roll_dogpile, t.eventually as eventually, t.canDeclare as can_declare, t.land as land, t.vassal as vassal, t.value as value, t.cmp as cmp, t.totalDef as total_def, t.totalDefFar as total_def_far, t.limDef as lim_def, t.targetWars as target_wars, t.dogpile as dogpile, t.dogReach as dog_reach, t.adj as adj, t.land0 as land0, t.capAlone as cap_alone, t.vic4 as vic4 from (select p, unnest(p.war.targets) t from pl where p.war is not null);
drop table pl;
